package in.jharkhand.civic.service;
import in.jharkhand.civic.repository.JsonStore; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.*;
@Service public class AuditService { private final JsonStore store; private final IdService ids; public AuditService(JsonStore s,IdService i){store=s;ids=i;} public void log(String actorId,String role,String action,String entityType,String entityId,Object previous,Object next){Map<String,Object> x=new LinkedHashMap<>();x.put("id",ids.id("audit"));x.put("actorId",actorId);x.put("actorRole",role);x.put("action",action);x.put("entityType",entityType);x.put("entityId",entityId);x.put("previousValue",previous);x.put("newValue",next);x.put("timestamp",Instant.now().toString());store.add("audit-logs.json",x);} }
